import {projectMiniature} from './miniature-raster.js?v=architecture-collection-51';
export const GEYSER_ORIGIN=[-.08,-.08,.18];
// World-state indication on the existing scenery clock; no new timer or UI transition.
export function geyserPlumeState(renderer,root){const c=renderer.getCity();let access=false,active=root.type==='geyserPark'&&renderer.layer==='city'&&c.finance.roadCondition>20;for(let y=root.y;y<root.y+5;y++)for(let x=root.x;x<root.x+5;x++){const t=c.tiles[y*c.size+x];if(!t||t.root!==root.root||!t.powered||t.fire||t.rubble||t.radiation)active=false;access ||= !!t?.roadIds?.length;}return{active:active&&access,time:renderer.preferences?.sceneryAnimations===false||renderer.reducedMotion.matches?0:renderer.vehicleTime};}
export function geyserDroplets(time=0){return Array.from({length:56},(_,i)=>{const f=((time*.65+i/56)%1+1)%1,angle=i*2.399963229728653,spread=.095*f;return{point:[GEYSER_ORIGIN[0]+Math.cos(angle)*spread,GEYSER_ORIGIN[1]+Math.sin(angle)*spread,GEYSER_ORIGIN[2]+.58*4*f*(1-f)],color:i%3?'#d7edf0':'#a5d6df'};});}
export function geyserPlumePixels(time=0,rotation=0,depth){const pixels=[];for(const {point,color} of geyserDroplets(time)){const [x,y,z]=point,[rx,ry]=rotation===0?[x,y]:rotation===1?[-y,x]:rotation===2?[-x,-y]:[y,-x],p=projectMiniature(point,rotation),d=rx+ry+z;for(let dy=-2;dy<=2;dy++)for(let dx=-1;dx<=1;dx++){const px=Math.round(p[0])+dx,py=Math.round(p[1])+dy;if(px>=0&&px<512&&py>=0&&py<512&&(!depth||d>=depth[py*512+px]-1e-7))pixels.push({x:px,y:py,color});}}return pixels;}
